&lt;li style=&quot;color: rgb(73, 73, 73) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(73, 73, 73); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Excellent communication and presentation skills with a keen ability to explain complex technical concepts to both technical and non-technical stakeholders&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(73, 73, 73) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(73, 73, 73); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Strong problem-solving and analytical skills&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(73, 73, 73) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(73, 73, 73); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Experience with Oracle, SQL Server, Postgres, MySQL, and NoSQL databases&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(73, 73, 73) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(73, 73, 73); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Hands on experience with other data replication or ETL tools&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(73, 73, 73) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(73, 73, 73); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Experience with self-hosted software applications and supporting infrastructure&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(73, 73, 73) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(73, 73, 73); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Hands on networking experience both in the cloud and on-premise&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Bonus Skills​&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;color: rgb(73, 73, 73) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(73, 73, 73); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Experience developing partner relationships&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(73, 73, 73) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(73, 73, 73); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Specialized expertise in security posture&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(73, 73, 73) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(73, 73, 73); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Experience with self-hosted and SaaS software applications&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(73, 73, 73) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(73, 73, 73); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Hands on experience with DBT&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: rgb(73, 73, 73) !important; font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(73, 73, 73); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Docker/Podman/Kubernetes experience&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
